/**
 * Internationalization (i18n) Module
 * Provides comprehensive translations for English (US - default), Portuguese (BR), and Spanish (ES).
 * Fully covers Landing, Pricing, Auth, Account, Dashboard, Analytics, Trades, Setups, News, Holidays, Import, Settings, and Modals.
 */

export type Lang = 'en' | 'pt' | 'es';

export const getStoredLanguage = (): Lang => {
  try {
    const saved = localStorage.getItem('quantara_app_language');
    if (saved === 'pt' || saved === 'es' || saved === 'en') return saved;
  } catch (e) {
    // Ignore error
  }
  return 'en';
};

export const setStoredLanguage = (lang: Lang) => {
  try {
    localStorage.setItem('quantara_app_language', lang);
  } catch (e) {
    // Ignore error
  }
};

