/**
 * Universal Translation function. Returns the translated string for the given key and language.
 * Falls back to English if key or language is not found.
 */
export function t(key: string, lang: string = 'en'): string {
  const entry = translations[key];
  if (!entry) return key;
  const l = (lang === 'pt' || lang === 'es' || lang === 'en') ? (lang as Lang) : 'en';
  return entry[l] || entry.en || key;
}

export default t;
